import type { DatabaseSync } from 'node:sqlite';
import { randomUUID } from 'node:crypto';

/** A job attempt whose lease is older than this is considered abandoned (its worker died). */
export const LEASE_MS = 3_000;
/** The worker counts as up if its heartbeat is at most this old. */
export const HEARTBEAT_STALE_MS = 3_000;

export interface JobRow {
  id: string;
  status: 'queued' | 'running' | 'completed' | 'failed';
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  run_after: number;
  lease_until: number | null;
  created_at: string;
  updated_at: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
}

export type SubmitOutcome = { kind: 'created' | 'replayed'; job: JobRow } | { kind: 'conflict' };

const iso = (ms: number): string => new Date(ms).toISOString();

/** Runs `fn` inside a write transaction that takes the write lock up front. */
function immediate<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let value: T;
  try {
    value = fn();
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
  db.exec('COMMIT');
  return value;
}

export function getJob(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as JobRow | undefined;
}

/** Newest first. */
export function listJobs(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY rowid DESC').all() as unknown as JobRow[];
}

/**
 * Creates a job, or replays/rejects according to the idempotency key. The key check and the insert
 * happen in one write transaction, so a key can never create two jobs.
 */
export function submitJob(db: DatabaseSync, job: NewJob, idempotencyKey: string | undefined, now: number): SubmitOutcome {
  return immediate(db, (): SubmitOutcome => {
    if (idempotencyKey !== undefined) {
      const existing = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?').get(idempotencyKey) as JobRow | undefined;
      if (existing) {
        const same = existing.input === job.input && existing.steps === job.steps && existing.fail_attempts === job.failAttempts;
        return same ? { kind: 'replayed', job: existing } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const ts = iso(now);
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
    ).run(id, job.input, job.steps, job.failAttempts, idempotencyKey ?? null, ts, ts);
    return { kind: 'created', job: getJob(db, id)! };
  });
}

export function isWorkerUp(db: DatabaseSync, now: number): boolean {
  const row = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1').get() as { beat_at: number } | undefined;
  return row !== undefined && now - row.beat_at <= HEARTBEAT_STALE_MS;
}

export function writeHeartbeat(db: DatabaseSync, now: number): void {
  db.prepare(
    'INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT (id) DO UPDATE SET beat_at = excluded.beat_at',
  ).run(now);
}

export function clearHeartbeat(db: DatabaseSync): void {
  db.prepare('DELETE FROM worker_heartbeat WHERE id = 1').run();
}

/** Re-queues running jobs whose worker stopped refreshing their lease (for example after SIGKILL). */
export function reclaimExpiredLeases(db: DatabaseSync, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', lease_until = NULL, run_after = 0, completed = 0, updated_at = ?
     WHERE status = 'running' AND lease_until < ?`,
  ).run(iso(now), now);
}

/** Atomically takes the oldest runnable queued job and starts an attempt on it. */
export function claimNextJob(db: DatabaseSync, now: number): JobRow | undefined {
  return immediate(db, () => {
    const next = db
      .prepare(`SELECT id FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY rowid LIMIT 1`)
      .get(now) as { id: string } | undefined;
    if (!next) return undefined;
    db.prepare(
      `UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, lease_until = ?, updated_at = ?
       WHERE id = ?`,
    ).run(now + LEASE_MS, iso(now), next.id);
    return getJob(db, next.id);
  });
}

export function updateProgress(db: DatabaseSync, id: string, completed: number, now: number): void {
  db.prepare(
    `UPDATE jobs SET completed = ?, lease_until = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
  ).run(completed, now + LEASE_MS, iso(now), id);
}

export function completeJob(db: DatabaseSync, id: string, output: string, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, completed = steps, lease_until = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(output, iso(now), id);
}

export function failJob(db: DatabaseSync, id: string, message: string, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, lease_until = NULL, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(message, iso(now), id);
}

/** Returns a running job to the queue, to be picked up again once `runAfter` (epoch ms) has passed. */
export function requeueJob(db: DatabaseSync, id: string, runAfter: number, now: number): void {
  db.prepare(
    `UPDATE jobs SET status = 'queued', completed = 0, lease_until = NULL, run_after = ?, updated_at = ?
     WHERE id = ? AND status = 'running'`,
  ).run(runAfter, iso(now), id);
}

/** Gives back a running job during graceful shutdown so another worker can take it at once. */
export function releaseJob(db: DatabaseSync, id: string, now: number): void {
  requeueJob(db, id, 0, now);
}

/** The JSON shape returned by every endpoint that returns a job. */
export function toJobJson(r: JobRow) {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.completed, total: r.steps },
    result: r.status === 'completed' ? { output: r.result_output ?? '' } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

