import type { NewJob } from './store.ts';

export interface FieldError {
  field: string;
  message: string;
}

export type ParseResult = { ok: true; job: NewJob; idempotencyKey: string | undefined } | { ok: false; fields: FieldError[] };

const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

/** Validates a `POST /api/jobs` request. Collects every offending field rather than stopping at the first. */
export function parseSubmission(
  contentType: string | undefined,
  rawBody: string,
  idempotencyHeader: string | string[] | undefined,
): ParseResult {
  const fields: FieldError[] = [];

  let idempotencyKey: string | undefined;
  if (idempotencyHeader !== undefined) {
    const value = Array.isArray(idempotencyHeader) ? idempotencyHeader.join(', ') : idempotencyHeader;
    if (IDEMPOTENCY_KEY_RE.test(value)) idempotencyKey = value;
    else fields.push({ field: 'Idempotency-Key', message: 'must be 1-128 characters from A-Z, a-z, 0-9, "_" or "-"' });
  }

  const mediaType = (contentType ?? '').split(';')[0]!.trim().toLowerCase();
  if (mediaType !== 'application/json') {
    fields.unshift({ field: 'body', message: 'Content-Type must be application/json' });
    return { ok: false, fields };
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    fields.unshift({ field: 'body', message: 'body must be valid JSON' });
    return { ok: false, fields };
  }
  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    fields.unshift({ field: 'body', message: 'body must be a JSON object' });
    return { ok: false, fields };
  }

  const obj = parsed as Record<string, unknown>;
  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  let input = '';
  const rawInput = Object.hasOwn(obj, 'input') ? obj.input : undefined;
  if (typeof rawInput !== 'string') {
    fields.push({ field: 'input', message: rawInput === undefined ? 'is required' : 'must be a string' });
  } else if (rawInput.trim() === '') {
    fields.push({ field: 'input', message: 'must not be blank' });
  } else if (rawInput.length > 1000) {
    fields.push({ field: 'input', message: 'must be at most 1000 characters' });
  } else {
    input = rawInput;
  }

  const steps = intField(obj, 'steps', 1, 20, 5, fields);
  const failAttempts = intField(obj, 'failAttempts', 0, 5, 0, fields);

  if (fields.length > 0 || steps === undefined || failAttempts === undefined) return { ok: false, fields };
  return { ok: true, job: { input, steps, failAttempts }, idempotencyKey };
}

function intField(obj: Record<string, unknown>, name: string, min: number, max: number, fallback: number, fields: FieldError[]): number | undefined {
  if (!Object.hasOwn(obj, name)) return fallback;
  const value = obj[name];
  if (typeof value !== 'number' || !Number.isInteger(value) || value < min || value > max) {
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return undefined;
  }
  return value;
}

