import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { getJob, isWorkerUp, listJobs, submitJob, toJobJson } from './store.ts';
import { parseSubmission, type FieldError } from './validate.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const MAX_BODY_BYTES = 64 * 1024;

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  res.setHeader('allow', allow);
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Use ${allow}.`);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { text, tooLarge } = await readBody(req);
  const parsed = tooLarge
    ? { ok: false as const, fields: [{ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` }] }
    : parseSubmission(req.headers['content-type'], text, req.headers['idempotency-key']);
  if (!parsed.ok) {
    const names = parsed.fields.map((f) => f.field).join(', ');
    return sendError(res, 400, 'invalid_request', `Invalid request: ${names}.`, parsed.fields);
  }

  const outcome = submitJob(db, parsed.job, parsed.idempotencyKey, Date.now());
  if (outcome.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, outcome.kind === 'created' ? 201 : 200, toJobJson(outcome.job));
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (req.method !== 'GET') return methodNotAllowed(res, 'GET');
    return send(res, 200, { status: 'ok', worker: isWorkerUp(db, Date.now()) ? 'up' : 'down' });
  }

  if (pathname === '/') {
    if (req.method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (req.method === 'GET') return send(res, 200, { jobs: listJobs(db).map(toJobJson) });
    if (req.method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (req.method !== 'GET') return methodNotAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const job = getJob(db, id);
    if (!job) return sendError(res, 404, 'not_found', 'No such job.');
    return send(res, 200, toJobJson(job));
  }

  sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  });
});

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

