import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import {
  claimNextJob,
  clearHeartbeat,
  completeJob,
  failJob,
  reclaimExpiredLeases,
  releaseJob,
  requeueJob,
  updateProgress,
  writeHeartbeat,
  type JobRow,
} from './store.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const HEARTBEAT_MS = 1_000;
const RETRY_DELAY_MS = 500;
/** Total attempts allowed for transient failures. */
const MAX_ATTEMPTS = 3;

const db = openDatabase();
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

const heartbeat = () => writeHeartbeat(db, Date.now());
heartbeat();
const heartbeatTimer = setInterval(heartbeat, HEARTBEAT_MS);

/** Runs one attempt of `job`. `job.attempts` already includes this attempt. */
async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: fails at the first step, before any progress.
    await sleep(STEP_MS);
    const now = Date.now();
    if (attempt >= MAX_ATTEMPTS) failJob(db, job.id, 'transient failure', now);
    else requeueJob(db, job.id, now + RETRY_DELAY_MS, now);
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(STEP_MS);
    if (stopping) {
      releaseJob(db, job.id, Date.now());
      return;
    }
    updateProgress(db, job.id, step, Date.now());
  }
  completeJob(db, job.id, job.input.toUpperCase(), Date.now());
}

console.log('worker started');
while (!stopping) {
  reclaimExpiredLeases(db, Date.now());
  const job = claimNextJob(db, Date.now());
  if (!job) {
    await sleep(POLL_MS);
    continue;
  }
  await runAttempt(job);
}

clearInterval(heartbeatTimer);
clearHeartbeat(db);
db.close();
console.log('worker stopped');
process.exit(0);

