import { spawn } from 'node:child_process';
import { createServer } from 'node:net';
import { mkdtempSync } from 'node:fs';
import { join } from 'node:path';
import { setTimeout as sleep } from 'node:timers/promises';

const APP = process.argv[2];
const T = mkdtempSync(join(process.env.TMPDIR, 'jt-'));
const DB = join(T, 'jobs.db');
const port = await new Promise((res) => { const s = createServer().listen(0, '127.0.0.1', () => { const p = s.address().port; s.close(() => res(p)); }); });
const base = `http://127.0.0.1:${port}`;
const env = { ...process.env, PORT: String(port), DATABASE_PATH: DB };
let server, worker;
const start = (name) => spawn('node', ['--disable-warning=ExperimentalWarning', join(APP, name)], { env, stdio: ['ignore', 'inherit', 'inherit'] });
async function req(method, path, body, headers = {}) {
  const r = await fetch(base + path, { method, headers: { 'content-type': 'application/json', ...headers }, body });
  const text = await r.text(); let json; try { json = JSON.parse(text); } catch {}
  return { status: r.status, ct: r.headers.get('content-type'), json, text };
}
const post = (obj, headers) => req('POST', '/api/jobs', typeof obj === 'string' ? obj : JSON.stringify(obj), headers);
let fails = 0;
function check(name, cond, extra = '') { console.log(`${cond ? 'PASS' : 'FAIL'} ${name} ${cond ? '' : JSON.stringify(extra)}`); if (!cond) fails++; }
async function until(fn, ms) { const end = Date.now() + ms; for (;;) { const v = await fn().catch(() => undefined); if (v) return v; if (Date.now() > end) return undefined; await sleep(100); } }
const finished = (id, ms = 15000) => until(async () => { const r = await req('GET', `/api/jobs/${id}`); return ['completed', 'failed'].includes(r.json?.status) ? r.json : undefined; }, ms);

server = start('server.js'); worker = start('worker.js');
const up = await until(async () => (await req('GET', '/health')).json?.worker === 'up', 10000);
check('worker up within 10s', !!up);

// validation
let r = await post({ input: '   ', steps: '3', failAttempts: 9, colour: 1 });
check('validation 400 + fields', r.status === 400 && r.json.error.code === 'invalid_request', r);
const names = r.json.error.fields.map((f) => f.field).sort();
check('validation names each field', JSON.stringify(names) === JSON.stringify(['colour', 'failAttempts', 'input', 'steps']), names);
r = await post('[1]'); check('array body -> body field', r.status === 400 && r.json.error.fields[0].field === 'body', r.text);
r = await post('{bad'); check('malformed JSON -> 400', r.status === 400 && r.json.error.fields[0].field === 'body', r.text);
r = await req('POST', '/api/jobs', '{"input":"x"}', { 'content-type': 'text/plain' }); check('text/plain -> 400', r.status === 400, r.text);
r = await req('POST', '/api/jobs', '{"input":"x"}', { 'content-type': '' }); check('missing content-type -> 400', r.status === 400, r.text);
r = await post({ input: 'x'.repeat(1001) }); check('1001 chars -> 400', r.status === 400 && r.json.error.fields[0].field === 'input', r.text);
r = await post({ input: 'x'.repeat(1000) }); check('1000 chars -> 201', r.status === 201, r.text);
r = await post({ input: 'a', steps: 1.5 }); check('steps 1.5 -> 400', r.status === 400, r.text);
r = await post({ input: 'a', steps: 21 }); check('steps 21 -> 400', r.status === 400, r.text);
r = await post({ input: 'a', steps: null }); check('steps null -> 400', r.status === 400, r.text);
r = await post({ input: ' a b ' }); check('input stored exactly as sent', r.status === 201 && r.json.input === ' a b ', r.text);
r = await post({ input: 'a' }, { 'idempotency-key': 'bad key!' }); check('bad idem key -> 400 field', r.status === 400 && r.json.error.fields[0].field === 'Idempotency-Key', r.text);
r = await req('DELETE', '/api/jobs'); check('DELETE /api/jobs 405', r.status === 405 && r.json.error.code === 'method_not_allowed', r.text);
r = await req('GET', '/nope'); check('unknown path 404', r.status === 404 && r.json.error.code === 'not_found', r.text);
r = await req('GET', '/api/jobs/zzz'); check('missing job 404', r.status === 404, r.text);
r = await req('GET', '/'); check('UI served', r.status === 200 && r.text.includes('data-testid="job-form"') && r.text.includes('job-result'), r.status);

// idempotency
const k1 = await post({ input: 'idem-a' }, { 'idempotency-key': 'k1' });
const k2 = await post({ input: 'idem-a', steps: 5, failAttempts: 0 }, { 'idempotency-key': 'k1' });
const k3 = await post({ input: 'idem-b' }, { 'idempotency-key': 'k1' });
check('idem first 201', k1.status === 201, k1.text);
check('idem replay 200 same id', k2.status === 200 && k2.json.id === k1.json.id, k2.text);
check('idem conflict 409', k3.status === 409 && k3.json.error.code === 'idempotency_conflict', k3.text);

// retries and failure
const ok2 = await post({ input: 'retry me', steps: 1, failAttempts: 2 });
const done2 = await finished(ok2.json.id);
check('failAttempts 2 completes on attempt 3', done2?.status === 'completed' && done2.attempts === 3 && done2.result?.output === 'RETRY ME', done2);
const bad = await post({ input: 'doomed', steps: 2, failAttempts: 3 });
const doneBad = await finished(bad.json.id);
check('failAttempts 3 fails', doneBad?.status === 'failed' && doneBad.error === 'transient failure' && doneBad.result === null && doneBad.attempts === 3, doneBad);

// progress observable
const slow = await post({ input: 'progress', steps: 20 });
const seen = await until(async () => { const j = (await req('GET', `/api/jobs/${slow.json.id}`)).json; return j.progress.completed > 0 && j.status === 'running' ? j : undefined; }, 5000);
check('progress observable while running', !!seen, seen);

// crash recovery: SIGKILL worker mid-job, then restart
const crash = await post({ input: 'survive', steps: 20 });
await until(async () => (await req('GET', `/api/jobs/${crash.json.id}`)).json.progress.completed >= 3, 5000);
worker.kill('SIGKILL'); await sleep(300);
worker = start('worker.js');
const doneCrash = await finished(crash.json.id, 10000);
check('running job after SIGKILL completes', doneCrash?.status === 'completed' && doneCrash.result?.output === 'SURVIVE', doneCrash);

// server SIGKILL and restart: data persists
const jobsBefore = (await req('GET', '/api/jobs')).json.jobs.length;
server.kill('SIGKILL'); await sleep(300);
server = start('server.js');
await until(async () => (await req('GET', '/health')).status === 200, 10000);
const jobsAfter = (await req('GET', '/api/jobs')).json.jobs.length;
check('jobs persist across server SIGKILL', jobsBefore === jobsAfter && jobsAfter > 0, { jobsBefore, jobsAfter });
const k1again = await post({ input: 'idem-a' }, { 'idempotency-key': 'k1' });
check('idempotency survives restart', k1again.status === 200 && k1again.json.id === k1.json.id, k1again.text);

// graceful shutdown
const exitOf = (p) => new Promise((res) => p.once('exit', (code, sig) => res({ code, sig })));
const wExit = exitOf(worker); const sExit = exitOf(server);
worker.kill('SIGTERM'); server.kill('SIGTERM');
const [we, se] = await Promise.all([Promise.race([wExit, sleep(5000)]), Promise.race([sExit, sleep(5000)])]);
check('worker exits on SIGTERM', we && (we.code === 0 || we.sig === null), we);
check('server exits on SIGTERM', se && (se.code === 0 || se.sig === null), se);

console.log(fails === 0 ? 'ALL PASSED' : `${fails} FAILED`, T);
server.kill('SIGKILL'); worker.kill('SIGKILL');
process.exit(fails ? 1 : 0);
EOF
